import sys,numpy as np
sys.path.insert(0,'/app'); import limited_client as r
o=r.observe('corner4');I=o['rgb'];D=o['depth_m']; K=o['intrinsic'];T=o['camera_to_world']
for region in [(165,195,185,220),(145,180,200,250)]:
 x0,y0,x1,y1=region
 for y in range(y0,y1):
  for x in range(x0,x1):
   R,G,B=I[y,x]
   if R>70 and R>G*1.15 and G>B*1.1 and D[y,x]<1.3:
    print('pix',x,y,'rgb',I[y,x].tolist(),'d',D[y,x]);
    cam=np.array([(x-K[0,2])*D[y,x]/K[0,0],(y-K[1,2])*D[y,x]/K[1,1],D[y,x],1]);print('world',(T@cam)[:3]);raise SystemExit
